insert into public.it_frameworks (
  id, status, name, slug, short_description, problem_statement, outcome_statement,
  target_audience, when_to_use, when_not_to_use, method_summary, journey_stage_id,
  priority_score, priority_rationale, source_strength, source_note, flagship,
  display_order, seo_title, seo_description, published_at
) values (
  '3aa044a5-b513-0185-8621-fdd2faa7684b', 'published', 'Business Model Chooser', 'business-model-chooser', 'Choose the structural business model that actually fits how your product delivers value, before you price it.', 'Founders default to whichever business model is fashionable — usually SaaS, because that''s what most startup advice assumes — without checking whether it actually fits who pays them, how their product delivers value, and how they''ll realistically grow. The wrong structural model makes every later decision, including pricing, harder than it needs to be.', 'A recommended business model, a runner-up, and the one factor that separated them.',
  'Founders who''ve validated a problem worth solving and now need to decide the commercial shape of the business before building or pricing it.', 'Use once you know what problem you''re solving and for whom, before you scope what to build or decide how to price it.', 'Not useful before you''ve validated that the underlying problem is real — that''s what Product Idea Assessor and Customer Discovery Kit are for.', 'Work out whether your product connects two distinct kinds of users or serves one audience directly, who actually pays you (the end user, a third-party advertiser, or a fee on each transaction), whether value is delivered as ongoing access or in discrete completed transactions, and what growth lever you can realistically pull. Combining these rules ranks four named candidate models — SaaS, Marketplace, Transactional and Advertising — so you get a recommended model and the runner-up it beat.', '3f7a87a9-2a65-573c-b0ed-c66ad4f7d9f0',
  87, 'Ranked #10 in the source-material opportunity portfolio (spec v4 §37) and the fourth Tier 2 family. Reuses Pricing Your Product''s named-candidate scoring mechanic (four models scored across four dimensions) rather than introducing a new one, and gives founders the structural business-model decision that logically precedes Pricing Your Product''s pricing-mechanic decision within it — it points forward to Pricing Your Product as its next step.', 'strong', 'Developed from A Bit Gamey material on choosing a business model, including the SaaS/Marketplace/Transactional/Advertising distinctions, who pays, cold-start problems and growth levers by model.', false,
  10, 'Business Model Chooser — choose the right business model before you price it', 'Work out whether SaaS, Marketplace, Transactional or Advertising actually fits how your product delivers value and who pays for it.', '2026-08-11T09:00:00Z'
)
