insert into public.it_frameworks (
  id, status, name, slug, short_description, problem_statement, outcome_statement,
  target_audience, when_to_use, when_not_to_use, method_summary, journey_stage_id,
  priority_score, priority_rationale, source_strength, source_note, flagship,
  display_order, seo_title, seo_description, published_at
) values (
  '56a1d86d-13dc-5eed-5d9f-28d2db214936', 'published', 'Decision Framework Picker', 'decision-framework-picker', 'Pick the right thinking technique — Six Thinking Hats, First Principles, a Razor or the Boundary Rule — for the decision actually in front of you.', 'Founders default to whichever thinking technique they used last time, or to no deliberate technique at all, regardless of whether it fits the decision at hand. A framework built for a group discussion doesn''t help with a quick daily choice, and a quick rule of thumb doesn''t help with a genuinely novel problem — reaching for the wrong tool wastes either time or rigour.', 'A recommended thinking framework, a runner-up, and the one factor that separated them.',
  'Founders facing a lot of differently-shaped everyday decisions who want a quick reference rather than a deep process for each one.', 'Use whenever a decision shows up and you''re not sure which technique actually fits it.', 'Not a substitute for Better Decision Maker''s deeper process when a decision is genuinely consequential and hard to reverse — use that instead.', 'Work out whether multiple people or perspectives are involved, what shape the choice takes (a sequence of candidates, one decision to reason through, or a small frequent choice), whether there''s a clear existing approach to copy, and how much time the decision actually warrants. Combining these ranks four named frameworks — Six Thinking Hats, First Principles Thinking, Razors and the Boundary Rule — so you get a recommended technique and the runner-up it beat.', '3f7a87a9-2a65-573c-b0ed-c66ad4f7d9f0',
  86, 'Ranked #11 in the source-material opportunity portfolio (spec v4 §37) and the fifth Tier 2 family. Reuses the named-candidate scoring mechanic a third time (Pricing Your Product, Business Model Chooser). Its four candidate frameworks are deliberately distinct from Better Decision Maker''s own four techniques (reversibility, inversion, simple rules, expected value — see the Decision Worksheet template) so this family offers a genuinely different menu rather than re-picking what Better Decision Maker already bundles into one process. No next-step family is set — picking a thinking technique doesn''t causally lead to one particular next family the way Business Model Chooser leads to Pricing Your Product.', 'strong', 'Developed from A Bit Gamey material on decision-making techniques, including Six Thinking Hats, first principles thinking, razors/rules of thumb, and boundary/stopping rules for sequential choices.', false,
  11, 'Decision Framework Picker — which thinking technique fits your decision', 'Work out whether Six Thinking Hats, First Principles Thinking, a Razor or the Boundary Rule fits the decision actually in front of you.', '2026-08-11T09:00:00Z'
)
