insert into public.it_frameworks (
  id, status, name, slug, short_description, problem_statement, outcome_statement,
  target_audience, when_to_use, when_not_to_use, method_summary, journey_stage_id,
  priority_score, priority_rationale, source_strength, source_note, flagship,
  display_order, seo_title, seo_description, published_at
) values (
  '8205be51-5547-9286-0ce3-a3da135056c2', 'published', 'Product Prioritisation Tool', 'product-prioritisation-tool', 'Work out which scheduling strategy actually fits your task list right now.', 'Founders order their task list on instinct — usually whatever feels most urgent — without ever naming what they''re actually trying to optimise. Deadline compliance, avoiding overload, momentum and getting the most valuable things done all call for a genuinely different order, and picking the wrong one wastes effort even when every individual task gets done well.', 'A recommended scheduling strategy, a runner-up, and the one factor that separated them.',
  'Founders and small teams with more tasks than time who want a deliberate way to decide what to work on next.', 'Use whenever your task list has grown past what you can hold in your head, or you''re not confident you''re working on the right thing.', 'Not useful for a single isolated decision — that''s what Better Decision Maker is for. This is for ordering a list of many tasks.', 'Work out whether your tasks have hard deadlines or flexible timing, whether everything is realistically achievable or something has to give, whether your tasks vary a lot in value, and what would help most right now — momentum or confidence nothing important slips. Combining these ranks four named scheduling strategies — Earliest Due Date, Moore''s Algorithm, Shortest Processing Time and Weighted Processing Time — so you get a recommended strategy and the runner-up it beat.', '81e350e5-2342-79a0-b21e-5ded01bef450',
  84, 'Ranked #14 in the source-material opportunity portfolio (spec v4 §37) and the eighth and final Tier 2 family. Its source material names four comparable scheduling strategies directly, so it reuses the named-candidate scoring mechanic. No next-step family is set — prioritising a task list is a recurring operational practice, not a one-time step that causally leads to one particular next family, the same reasoning Decision Framework Picker used (0031).', 'strong', 'Developed from A Bit Gamey material on task scheduling (Earliest Due Date, Moore''s Algorithm, Shortest Processing Time, Weighted Processing Time) and the Eisenhower importance/urgency decision matrix.', false,
  14, 'Product Prioritisation Tool — four ways to order your task list', 'Work out whether Earliest Due Date, Moore''s Algorithm, Shortest Processing Time or Weighted Processing Time fits your task list.', '2026-08-11T09:00:00Z'
)
